function litCur(string $src,string $key):?string{$p='~[\'\"]'.preg_quote($key,'~').'[\'\"]\s*=>\s*([\'\"])(.*?)\\1~s';return preg_match($p,$src,$m)?stripcslashes((string)$m[2]):null;}
function cfgCur(string $src):?array{$h=litCur($src,'host');$d=litCur($src,'dbname');$u=litCur($src,'username');$p=litCur($src,'password');return($h===null||$d===null||$u===null||$p===null)?null:['host'=>$h,'port'=>3306,'database'=>$d,'username'=>$u,'password'=>$p];}
function connCur(array $c):PDO{$p=new PDO('mysql:host='.$c['host'].';port='.($c['port']??3306).';dbname='.$c['database'].';charset=utf8mb4',$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$p->exec('SET SESSION TRANSACTION READ ONLY');$p->exec('START TRANSACTION READ ONLY');return$p;}
