$central=connCur($config['database']);$company=$central->query("SELECT * FROM companies WHERE id=25 AND status='active' LIMIT 1")->fetch();if(!$company)throw new RuntimeException('company unavailable');$tenant=connCur(companyDatabaseConfig($config,$company));if(!WasteTripService::schemaReady($tenant))throw new RuntimeException('Waste Trips schema unavailable');
$paths=array_values(array_unique(array_filter(array_map('trim',file($candidateList,FILE_IGNORE_NEW_LINES)?:[]))));$matches=[];foreach($paths as $path){if(!is_file($path)||filesize($path)>524288)continue;$src=@file_get_contents($path);if(!is_string($src))continue;$c=cfgCur($src);if(!$c)continue;try{$p=connCur($c);if(!hasFlightsCur($p))continue;$matches[hash('sha256',$c['host']."\0".$c['database']."\0".$c['username'])]=$c;}catch(Throwable){}}
if(count($matches)!==1)throw new RuntimeException('legacy connection count='.count($matches));$legacy=connCur(array_values($matches)[0]);
$candidates=WasteTripLegacyImportService::listCandidates($legacy,$tenant,500,true);if(count($candidates)!==75)throw new RuntimeException('candidate count='.count($candidates));
$links=0;$unique=[];$occ=[];$missing=[];$occupied=[];$routes=[];$statuses=[];$planning=['exact'=>0,'range'=>0,'partial'=>0,'unspecified'=>0];$customerInns=[];$massMissing=[];$massMismatch=[];$maxDelta=0.0;$ids=[];$detail=[];
foreach($candidates as $r){$fid=(int)$r['id'];$ids[]=$fid;$reqs=array_map('strval',$r['request_ids']??[]);$links+=count($reqs);foreach($reqs as $id){$key='id:'.$id;$unique[$key]=true;$occ[$key]=($occ[$key]??0)+1;}foreach(($r['missing_request_ids']??[]) as $id)$missing[(string)$id]=true;foreach(($r['occupied_requests']??[]) as $id=>$trip)$occupied[(string)$id]=(int)$trip;$routes[(string)($r['route_type']??'')]=($routes[(string)($r['route_type']??'')]??0)+1;$statuses[(string)($r['status']??'')]=($statuses[(string)($r['status']??'')]??0)+1;$p=WasteTripLegacyImportService::resolveLegacyPlanning($r);$planning[$p['mode']]++;if($p['partial_range'])$planning['partial']++;foreach(($r['customer_hints']??[]) as $h){$inn=trim((string)($h['inn']??''));if($inn!=='')$customerInns[]=$inn;}$legacyRaw=trim((string)($r['total_mass_tonn']??''));$delta=abs((float)($r['mass_delta_kg']??0));$maxDelta=max($maxDelta,$delta);if($legacyRaw===''||!is_numeric(str_replace(',','.',$legacyRaw)))$massMissing[]=$fid;elseif($delta>1.0)$massMismatch[]=['id'=>$fid,'delta_kg'=>$delta,'legacy_kg'=>$r['legacy_mass_kg'],'current_kg'=>$r['current_mass_kg']];if(in_array($fid,[241,258],true))$detail[$fid]=['id'=>$fid,'request_ids'=>$reqs,'request_count'=>count($reqs),'status'=>$r['status']??null,'route_type'=>$r['route_type']??null,'block_date'=>$r['block_date']??null,'planning'=>$p,'legacy_mass_kg'=>$r['legacy_mass_kg'],'current_mass_kg'=>$r['current_mass_kg'],'mass_delta_kg'=>$r['mass_delta_kg']];}
ksort($routes);ksort($statuses);sort($ids);$customerInns=array_values(array_unique($customerInns));sort($customerInns,SORT_STRING);$repeated=count(array_filter($occ,static fn(int $n):bool=>$n>1));
$clientStmt=$tenant->prepare('SELECT COUNT(*) FROM clients WHERE inn=?');$clientStmt->execute(['4714004270']);$clientCount=(int)$clientStmt->fetchColumn();$users=$tenant->query("SELECT id FROM users WHERE status='active' AND deleted_at IS NULL ORDER BY id")->fetchAll();$utilCols=array_column($tenant->query("SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='feo_utilizers'")->fetchAll(),'COLUMN_NAME');if(in_array('inn',$utilCols,true)){$u=$tenant->prepare("SELECT id FROM feo_utilizers WHERE is_active=1 AND inn=? ORDER BY id");$u->execute(['7703545931']);$utils=$u->fetchAll();}else{$utils=$tenant->query("SELECT id FROM feo_utilizers WHERE is_active=1 AND (UPPER(COALESCE(short_name,'')) LIKE '%ФРЕГАТ%' OR UPPER(COALESCE(full_name,'')) LIKE '%ФРЕГАТ%') ORDER BY id")->fetchAll();}
$out=['flights'=>count($candidates),'links'=>$links,'unique_feo'=>count($unique),'repeated_feo'=>$repeated,'flight_ids'=>$ids,'missing_feo'=>array_values(array_keys($missing)),'occupied_operational'=>$occupied,'route_counts'=>$routes,'status_counts'=>$statuses,'planning'=>$planning,'customer_inns'=>$customerInns,'feo_client_count'=>$clientCount,'active_users'=>array_map(static fn(array $r):int=>(int)$r['id'],$users),'utilizer_ids'=>array_map(static fn(array $r):int=>(int)$r['id'],$utils),'mass_missing_count'=>count($massMissing),'mass_missing_flights'=>$massMissing,'mass_mismatch_count'=>count($massMismatch),'mass_mismatches'=>array_slice($massMismatch,0,20),'max_abs_mass_delta_kg'=>$maxDelta,'detail'=>$detail];
